  | Idle
  | Active
  | Completed
  | Failed

// Transition: state x event -> state
// Invalid transitions stay in current state
method Transition(current: State, event: string) returns (next: State)
  ensures next == Idle || next == Active || next == Completed || next == Failed
{
  match current
  case Idle =>
    if event == "start" {
      next := Active;
    } else {
      next := Idle;
    }
  case Active =>
    if event == "complete" {
      next := Completed;
    } else if event == "fail" {
      next := Failed;
    } else {
      next := Active;
    }
  case Completed =>
    if event == "reset" {
      next := Idle;
    } else {
      next := Completed;
    }
  case Failed =>
    if event == "reset" {
      next := Idle;
    } else {
      next := Failed;
    }
}

